import os
from pathlib import Path


class LocalImageStorage:
    """Files in UPLOADS_DIR (a Docker volume in production). Names are generated by the API, never by the client."""

    def __init__(self, root: str | None = None, folder: str = "products"):
        self.root = Path(root or os.environ.get("UPLOADS_DIR", "/data/uploads")) / folder
        self.root.mkdir(parents=True, exist_ok=True)

    def save(self, name, data):
        tmp = self.root / f".{name}.tmp"
        tmp.write_bytes(data)
        tmp.replace(self.root / name)  # atomic: a half-written file is never served

    def path(self, name):
        return self.root / name

    def delete(self, name):
        (self.root / name).unlink(missing_ok=True)
